<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientJwksJsonAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientJwksJsonAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientJwksJsonAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getJwksJson returns null on a freshly created holder.
     */
    public function testJwksJsonNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientJwksJsonAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isJwksJsonAssigned());
        $this->assertNull($holder->getJwksJson());
    }
}
class ImplWithTrustedClientJwksJsonAttributeHolderUnitTest
{
    use TrustedClientJwksJsonAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedJwksJsonRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultJwksJson();
    }
}
